import http from 'k6/http';
import { check } from 'k6';
import exec from 'k6/execution';
import { SharedArray } from 'k6/data';

// Load the users generated by the Go setup script
const users = new SharedArray('users', function () {
    return JSON.parse(open('./users.json'));
});

export const options = {
    scenarios: {
        booking_test: {
            executor: 'shared-iterations',
            vus: 2000,          // 2,000 Concurrent Virtual Users
            iterations: 100000, // Exactly 100,000 requests to match our 100,000 users
            maxDuration: '5m',
        },
    },
};

export default function () {
    const index = exec.scenario.iterationInTest;
    const user = users[index];

    const url = 'http://localhost:8080/api/v1/me/registrations';
    const payload = JSON.stringify({
        exam_session_id: user.exam_session_id
    });

    const params = {
        headers: {
            'Content-Type': 'application/json',
            'Authorization': 'Bearer ' + user.token
        },
    };

    const res = http.post(url, payload, params);

    check(res, {
        'status is 201 (Booked)': (r) => r.status === 201,
        'status is 409 (Conflict/Duplicate/No Seat)': (r) => r.status === 409,
        'status is not 500': (r) => r.status !== 500,
    });
}
